// Helper function to define the concept of minimum sub-array sum
function MinSubArraySum(nums: seq<int>) : int
    requires |nums| > 0
    ensures forall (i: int, j: int :: 0 <= i <= j < |nums| ==> 
                     MinSubArray(nums, i, j) == MinSubArraySum(nums) // The minimum sub-array sum is correctly computed
                    )
{
    var minSum := nums[0];
    var currentSum := 0;

    // Iterate through the array to find the minimum sub-array sum
    for i := 0 to |nums| - 1
        invariant 0 <= i <= |nums|
        invariant currentSum + minSum < 0 // The current sum plus the minimum sum should be negative
    {
        currentSum := currentSum + nums[i];
        if currentSum < minSum {
            minSum := currentSum;
        }
        if currentSum > 0 {
            currentSum := 0; // Reset currentSum if it becomes positive
        }
    }
    return minSum;
}
